			{
				return false;
			}
			if (pageIndex >= PageCount || _pageIndex == pageIndex)
			{
				return false;
			}
			if (!OkToChangeCurrent())
			{
				return false;
			}
			if (RaisePageChanging(pageIndex) && pageIndex != -1)
			{
				return false;
			}
			if (CurrentAddItem != null || CurrentEditItem != null)
			{
