		/// <summary>
		/// Gets or sets the most recent index where activity took place
		/// </summary>
		internal int LastIndex { get; set; }

		/// <summary>
		/// Gets the first item (leaf) added to this group.  If this can't be determined,
		/// DependencyProperty.UnsetValue.
		/// </summary>
		internal object SeedItem
		{
			get
			{
				if (base.ItemCount > 0 && (GroupBy == null || GroupBy.GroupKeys.Count == 0))
				{
					int i = 0;
					for (int count = ((IReadOnlyCollection<object>)base.Items).Count; i < count; i++)
					{
						if (!(((IReadOnlyList<object>)base.Items)[i] is DataGridCollectionViewGroupInternal dataGridCollectionViewGroupInternal))
						{
							return ((IReadOnlyList<object>)base.Items)[i];
						}
						if (dataGridCollectionViewGroupInternal.ItemCount > 0)
						{
							return dataGridCollectionViewGroupInternal.SeedItem;
						}
					}
					return AvaloniaProperty.UnsetValue;
				}
				return AvaloniaProperty.UnsetValue;
			}
		}

