		/// <summary>
		/// Finds the index of the specified item
		/// </summary>
		/// <param name="item">Item we are looking for</param>
		/// <param name="seed">Seed of the item we are looking for</param>
		/// <param name="comparer">Comparer used to find the item</param>
		/// <param name="low">Low range of item index</param>
		/// <param name="high">High range of item index</param>
		/// <returns>Index of the specified item</returns>
		protected virtual int FindIndex(object item, object seed, IComparer comparer, int low, int high)
		{
			int i;
			if (comparer != null)
			{
				if (comparer is ListComparer listComparer)
				{
					listComparer.Reset();
				}
				if (comparer is CollectionViewGroupComparer collectionViewGroupComparer)
				{
					collectionViewGroupComparer.Reset();
				}
				for (i = low; i < high; i++)
				{
					object obj = ((base.ProtectedItems[i] is DataGridCollectionViewGroupInternal dataGridCollectionViewGroupInternal) ? dataGridCollectionViewGroupInternal.SeedItem : base.ProtectedItems[i]);
					if (obj != AvaloniaProperty.UnsetValue && comparer.Compare(seed, obj) < 0)
					{
						break;
					}
				}
			}
			else
			{
				i = high;
			}
			return i;
		}

		/// <summary>
		/// Returns an enumerator over the leaves governed by this group
		/// </summary>
		/// <returns>Enumerator of leaves</returns>
		internal IEnumerator GetLeafEnumerator()
		{
			return new LeafEnumerator(this);
		}

		/// <summary>
		/// Insert a new item or subgroup and return its index.  Seed is a
		/// representative from the subgroup (or the item itself) that
		/// is used to position the new item/subgroup w.r.t. the order given
		/// by the comparer. (If comparer is null, just add at the end).
		/// </summary>
		/// <param name="item">Item we are looking for</param>
		/// <param name="seed">Seed of the item we are looking for</param>
		/// <param name="comparer">Comparer used to find the item</param>
		/// <returns>The index where the item was inserted</returns>
		internal int Insert(object item, object seed, IComparer comparer)
		{
			int low = ((GroupBy != null) ? GroupBy.GroupKeys.Count : 0);
			int num = FindIndex(item, seed, comparer, low, base.ProtectedItems.Count);
			ChangeCounts(item, 1);
			base.ProtectedItems.Insert(num, item);
			return num;
		}

		/// <summary>
		/// Return the item at the given index within the list of leaves governed
		/// by this group
		/// </summary>
		/// <param name="index">Index of the leaf</param>
		/// <returns>Item at given index</returns>
		internal object LeafAt(int index)
		{
			int i = 0;
			for (int count = ((IReadOnlyCollection<object>)base.Items).Count; i < count; i++)
			{
				if (((IReadOnlyList<object>)base.Items)[i] is DataGridCollectionViewGroupInternal dataGridCollectionViewGroupInternal)
				{
					if (index < dataGridCollectionViewGroupInternal.ItemCount)
					{
						return dataGridCollectionViewGroupInternal.LeafAt(index);
					}
					index -= dataGridCollectionViewGroupInternal.ItemCount;
				}
				else
				{
					if (index == 0)
					{
						return ((IReadOnlyList<object>)base.Items)[i];
					}
					index--;
				}
			}
			return null;
		}

		/// <summary>
		/// Returns the index of the given item within the list of leaves governed
		/// by the full group structure.  The item must be a (direct) child of this
		/// group.  The caller provides the index of the item within this group,
		/// if known, or -1 if not.
		/// </summary>
		/// <param name="item">Item we are looking for</param>
		/// <param name="index">Index of the leaf</param>
		/// <returns>Number of items under that leaf</returns>
		internal int LeafIndexFromItem(object item, int index)
		{
			int num = 0;
			DataGridCollectionViewGroupInternal dataGridCollectionViewGroupInternal = this;
			while (dataGridCollectionViewGroupInternal != null)
			{
				int i = 0;
				for (int count = ((IReadOnlyCollection<object>)dataGridCollectionViewGroupInternal.Items).Count; i < count && (index >= 0 || !object.Equals(item, ((IReadOnlyList<object>)dataGridCollectionViewGroupInternal.Items)[i])) && index != i; i++)
				{
					num += (((IReadOnlyList<object>)dataGridCollectionViewGroupInternal.Items)[i] as DataGridCollectionViewGroupInternal)?.ItemCount ?? 1;
				}
				item = dataGridCollectionViewGroupInternal;
				dataGridCollectionViewGroupInternal = dataGridCollectionViewGroupInternal.Parent;
				index = -1;
			}
			return num;
		}

		/// <summary>
		/// Returns the index of the given item within the list of leaves governed
		/// by this group
		/// </summary>
		/// <param name="item">Item we are looking for</param>
		/// <returns>Number of items under that leaf</returns>
		internal int LeafIndexOf(object item)
		{
			int num = 0;
			int i = 0;
			for (int count = ((IReadOnlyCollection<object>)base.Items).Count; i < count; i++)
			{
				if (((IReadOnlyList<object>)base.Items)[i] is DataGridCollectionViewGroupInternal dataGridCollectionViewGroupInternal)
				{
					int num2 = dataGridCollectionViewGroupInternal.LeafIndexOf(item);
					if (num2 >= 0)
					{
						return num + num2;
					}
					num += dataGridCollectionViewGroupInternal.ItemCount;
				}
				else
				{
					if (object.Equals(item, ((IReadOnlyList<object>)base.Items)[i]))
					{
						return num;
					}
					num++;
				}
			}
			return -1;
		}

		/// <summary>
		/// Removes the specified item from the collection
		/// </summary>
		/// <param name="item">Item to remove</param>
		/// <param name="returnLeafIndex">Whether we want to return the leaf index</param>
		/// <returns>Leaf index where item was removed, if value was specified. Otherwise '-1'</returns>
		internal int Remove(object item, bool returnLeafIndex)
		{
			int result = -1;
			int num = base.ProtectedItems.IndexOf(item);
			if (num >= 0)
			{
				if (returnLeafIndex)
				{
					result = LeafIndexFromItem(null, num);
				}
				ChangeCounts(item, -1);
				base.ProtectedItems.RemoveAt(num);
			}
			return result;
		}

		/// <summary>
		/// Removes an empty group from the PagedCollectionView grouping
		/// </summary>
		/// <param name="group">Empty subgroup to remove</param>
		private static void RemoveEmptyGroup(DataGridCollectionViewGroupInternal group)
		{
			DataGridCollectionViewGroupInternal parent = group.Parent;
			if (parent != null)
			{
				DataGridGroupDescription groupBy = parent.GroupBy;
				if (parent.ProtectedItems.IndexOf((object)group) >= groupBy.GroupKeys.Count)
				{
					parent.Remove(group, returnLeafIndex: false);
				}
			}
		}

		/// <summary>
		/// Update the item count of the CollectionViewGroup
		/// </summary>
		/// <param name="item">CollectionViewGroup to update</param>
		/// <param name="delta">Delta to change count by</param>
		protected void ChangeCounts(object item, int delta)
		{
			bool flag = !(item is DataGridCollectionViewGroup);
			for (DataGridCollectionViewGroupInternal dataGridCollectionViewGroupInternal = this; dataGridCollectionViewGroupInternal != null; dataGridCollectionViewGroupInternal = dataGridCollectionViewGroupInternal._parentGroup)
			{
				dataGridCollectionViewGroupInternal.FullCount += delta;
				if (flag)
				{
					dataGridCollectionViewGroupInternal.ProtectedItemCount += delta;
					if (dataGridCollectionViewGroupInternal.ProtectedItemCount == 0)
					{
						RemoveEmptyGroup(dataGridCollectionViewGroupInternal);
					}
				}
			}
			_version++;
		}
	}
