					{
						object cellValue = visibleColumn2.GetCellValue(item, visibleColumn2.ClipboardContentBinding);
						e2.ClipboardRowContent.Add(new DataGridClipboardCellContent(item, visibleColumn2, cellValue));
					}
					OnCopyingRowClipboardContent(e2);
					stringBuilder.Append(FormatClipboardContent(e2));
				}
				string stringAndRelease = StringBuilderCache.GetStringAndRelease(stringBuilder);
				if (!string.IsNullOrEmpty(stringAndRelease))
				{
					CopyToClipboard(stringAndRelease);
					return true;
				}
			}
			return false;
		}

		private async void CopyToClipboard(string text)
		{
			TopLevel topLevel = TopLevel.GetTopLevel((Visual)(object)this);
			IClipboard val = ((topLevel != null) ? topLevel.Clipboard : null);
			if (val != null)
			{
				await val.SetTextAsync(text);
			}
		}

		private void ResetValidationStatus()
		{
			if (EditingRow != null)
			{
				EditingRow.IsValid = true;
				if (EditingRow.Index != -1)
				{
					foreach (DataGridCell cell in EditingRow.Cells)
					{
						if (!cell.IsValid)
						{
							cell.IsValid = true;
							cell.UpdatePseudoClasses();
						}
					}
					EditingRow.ApplyState();
				}
			}
			IsValid = true;
			_validationSubscription?.Dispose();
			_validationSubscription = null;
		}

