		internal void InsertElementAt(int slot, int rowIndex, object item, DataGridRowGroupInfo groupInfo, bool isCollapsed)
		{
			bool flag = rowIndex != -1;
			if (isCollapsed)
			{
				InsertElement(slot, null, updateVerticalScrollBarOnly: true, isCollapsed: true, flag);
			}
			else if (SlotIsDisplayed(slot))
			{
				if (flag)
				{
					InsertElement(slot, (Control)(object)GenerateRow(rowIndex, slot, item), updateVerticalScrollBarOnly: false, isCollapsed: false, flag);
				}
				else
				{
					InsertElement(slot, (Control)(object)GenerateRowGroupHeader(slot, groupInfo), updateVerticalScrollBarOnly: false, isCollapsed: false, flag);
				}
			}
			else
			{
				InsertElement(slot, null, _vScrollBar == null || ((Visual)_vScrollBar).IsVisible, isCollapsed: false, flag);
			}
		}

