					if (!(propertyInfo == null) && propertyInfo.CanWrite && AllowEdit)
					{
						return !CanEdit(type);
					}
					return true;
				}
				if (DataType.GetIsReadOnly())
				{
					return true;
				}
			}
			return !AllowEdit;
		}

		public int IndexOf(object dataItem)
		{
			if (DataSource is DataGridCollectionView dataGridCollectionView)
			{
				return dataGridCollectionView.IndexOf(dataItem);
			}
			IList list = List;
			if (list != null)
			{
				return list.IndexOf(dataItem);
			}
			IEnumerable dataSource = DataSource;
			if (dataSource != null && dataItem != null)
			{
				int num = 0;
				foreach (object item in dataSource)
				{
					if ((dataItem == null && item == null) || dataItem.Equals(item))
					{
						return num;
					}
					num++;
				}
			}
			return -1;
		}

		internal void ClearDataProperties()
		{
			_dataProperties = null;
		}

		/// <summary>
		/// Creates a collection view around the DataGrid's source. ICollectionViewFactory is
		/// used if the source implements it. Otherwise a PagedCollectionView is returned.
		/// </summary>
		/// <param name="source">Enumerable source for which to create a view</param>
		/// <returns>ICollectionView view over the provided source</returns>
		internal static IDataGridCollectionView CreateView(IEnumerable source)
		{
			IDataGridCollectionView dataGridCollectionView = null;
			if (source is IDataGridCollectionViewFactory dataGridCollectionViewFactory)
			{
				dataGridCollectionView = dataGridCollectionViewFactory.CreateView();
			}
			if (dataGridCollectionView == null)
			{
				dataGridCollectionView = new DataGridCollectionView(source);
			}
			return dataGridCollectionView;
		}

		internal static bool DataTypeIsPrimitive(Type dataType)
		{
			if (dataType != null)
			{
				Type nonNullableType = dataType.GetNonNullableType();
				if (!nonNullableType.IsPrimitive && !(nonNullableType == typeof(string)) && !(nonNullableType == typeof(DateTime)))
				{
					return nonNullableType == typeof(decimal);
				}
				return true;
			}
			return false;
		}

		internal void MoveCurrentTo(object item, int backupSlot, int columnIndex, DataGridSelectionAction action, bool scrollIntoView)
		{
			if (CollectionView != null)
			{
				_expectingCurrentChanged = true;
				_columnForCurrentChanged = columnIndex;
				_itemToSelectOnCurrentChanged = item;
				_selectionActionForCurrentChanged = action;
				_scrollForCurrentChanged = scrollIntoView;
				_backupSlotForCurrentChanged = backupSlot;
				CollectionView.MoveCurrentTo((item is DataGridCollectionViewGroup) ? null : item);
				_expectingCurrentChanged = false;
			}
		}

		internal void UnWireEvents(IEnumerable value)
		{
			if (value is INotifyCollectionChanged notifyCollectionChanged)
			{
				notifyCollectionChanged.CollectionChanged -= NotifyingDataSource_CollectionChanged;
			}
			if (SortDescriptions != null)
			{
				((AvaloniaList<DataGridSortDescription>)SortDescriptions).CollectionChanged -= CollectionView_SortDescriptions_CollectionChanged;
			}
			if (CollectionView != null)
			{
				CollectionView.CurrentChanged -= CollectionView_CurrentChanged;
				CollectionView.CurrentChanging -= CollectionView_CurrentChanging;
			}
			EventsWired = false;
		}

		internal void WireEvents(IEnumerable value)
		{
			if (value is INotifyCollectionChanged notifyCollectionChanged)
			{
				notifyCollectionChanged.CollectionChanged += NotifyingDataSource_CollectionChanged;
			}
			if (SortDescriptions != null)
			{
				((AvaloniaList<DataGridSortDescription>)SortDescriptions).CollectionChanged += CollectionView_SortDescriptions_CollectionChanged;
			}
			if (CollectionView != null)
			{
				CollectionView.CurrentChanged += CollectionView_CurrentChanged;
				CollectionView.CurrentChanging += CollectionView_CurrentChanging;
			}
			EventsWired = true;
		}

		private void CollectionView_CurrentChanged(object sender, EventArgs e)
		{
			if (_expectingCurrentChanged)
			{
				if (_itemToSelectOnCurrentChanged is DataGridCollectionViewGroup collectionViewGroup && _owner.RowGroupInfoFromCollectionViewGroup(collectionViewGroup) == null)
				{
					if (!_owner.IsSlotVisible(_backupSlotForCurrentChanged))
					{
						_backupSlotForCurrentChanged = _owner.GetNextVisibleSlot(_backupSlotForCurrentChanged);
					}
					if (_backupSlotForCurrentChanged >= _owner.SlotCount)
					{
						_backupSlotForCurrentChanged = _owner.GetPreviousVisibleSlot(_owner.SlotCount);
					}
					int rowIndex = -1;
					_itemToSelectOnCurrentChanged = _owner.ItemFromSlot(_backupSlotForCurrentChanged, ref rowIndex);
				}
				_owner.ProcessSelectionAndCurrency(_columnForCurrentChanged, _itemToSelectOnCurrentChanged, _backupSlotForCurrentChanged, _selectionActionForCurrentChanged, _scrollForCurrentChanged);
			}
			else if (CollectionView != null)
			{
				_owner.UpdateStateOnCurrentChanged(CollectionView.CurrentItem, CollectionView.CurrentPosition);
			}
		}

		private void CollectionView_CurrentChanging(object sender, DataGridCurrentChangingEventArgs e)
		{
			if (_owner.NoCurrentCellChangeCount == 0 && !_expectingCurrentChanged && !CommittingEdit && !_owner.CommitEdit())
			{
				if (e.IsCancelable)
				{
					e.Cancel = true;
				}
				else
				{
					_owner.CancelEdit(DataGridEditingUnit.Row, raiseEvents: false);
				}
			}
		}

		private void CollectionView_SortDescriptions_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (_owner.ColumnsItemsInternal.Count == 0)
			{
				return;
			}
			foreach (DataGridColumn item in _owner.ColumnsItemsInternal)
			{
				item.HeaderCell.UpdatePseudoClasses();
			}
		}

		private void NotifyingDataSource_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (_owner.LoadingOrUnloadingRow)
			{
				throw DataGridError.DataGrid.CannotChangeItemsWhenLoadingRows();
			}
			switch (e.Action)
			{
			case NotifyCollectionChangedAction.Add:
				if (ShouldAutoGenerateColumns)
				{
					_owner.InitializeElements(recycleRows: false);
				}
				else if (!IsGrouping)
				{
					_owner.InsertRowAt(e.NewStartingIndex);
				}
				break;
			case NotifyCollectionChangedAction.Remove:
				if (e.OldItems == null || e.OldStartingIndex < 0)
				{
					return;
				}
				if (IsGrouping)
				{
					break;
				}
				foreach (object oldItem in e.OldItems)
				{
					_owner.RemoveRowAt(e.OldStartingIndex, oldItem);
				}
				break;
			case NotifyCollectionChangedAction.Replace:
				throw new NotSupportedException();
			case NotifyCollectionChangedAction.Reset:
			{
				Type dataType = _dataType;
				_dataType = null;
				if (dataType != DataType)
				{
					ClearDataProperties();
					_owner.InitializeElements(recycleRows: false);
				}
				else
				{
					_owner.InitializeElements(!ShouldAutoGenerateColumns);
				}
				break;
			}
			}
			_owner.UpdatePseudoClasses();
		}

		private void UpdateDataProperties()
		{
			Type dataType = DataType;
			if (DataSource != null && dataType != null && !DataTypeIsPrimitive(dataType))
			{
				_dataProperties = dataType.GetProperties(BindingFlags.Instance | BindingFlags.Public);
			}
			else
			{
				_dataProperties = null;
			}
		}
	}
	internal class DataGridDisplayData
	{
		private Stack<DataGridRow> _fullyRecycledRows;

		private int _headScrollingElements;

		private DataGrid _owner;

		private Stack<DataGridRow> _recyclableRows;

		private List<Control> _scrollingElements;

		private Stack<DataGridRowGroupHeader> _fullyRecycledGroupHeaders;

		private Stack<DataGridRowGroupHeader> _recyclableGroupHeaders;

		public int FirstDisplayedScrollingCol { get; set; }

		public int FirstScrollingSlot { get; set; }

		public int LastScrollingSlot { get; set; }

		public int LastTotallyDisplayedScrollingCol { get; set; }

		public int NumDisplayedScrollingElements => _scrollingElements.Count;

		public int NumTotallyDisplayedScrollingElements { get; set; }

		internal double PendingVerticalScrollHeight { get; set; }

		public DataGridDisplayData(DataGrid owner)
		{
			_owner = owner;
			ResetSlotIndexes();
			FirstDisplayedScrollingCol = -1;
			LastTotallyDisplayedScrollingCol = -1;
			_scrollingElements = new List<Control>();
			_recyclableRows = new Stack<DataGridRow>();
			_fullyRecycledRows = new Stack<DataGridRow>();
			_recyclableGroupHeaders = new Stack<DataGridRowGroupHeader>();
			_fullyRecycledGroupHeaders = new Stack<DataGridRowGroupHeader>();
		}

		internal void AddRecyclableRow(DataGridRow row)
		{
			row.DetachFromDataGrid(recycle: true);
			_recyclableRows.Push(row);
		}

		internal DataGridRowGroupHeader? GetUsedGroupHeader()
		{
			if (_recyclableGroupHeaders.Count > 0)
			{
				return _recyclableGroupHeaders.Pop();
			}
			if (_fullyRecycledGroupHeaders.Count > 0)
			{
				DataGridRowGroupHeader dataGridRowGroupHeader = _fullyRecycledGroupHeaders.Pop();
				((AvaloniaObject)dataGridRowGroupHeader).ClearValue<bool>(Visual.IsVisibleProperty);
				return dataGridRowGroupHeader;
			}
			return null;
		}

		internal void AddRecylableRowGroupHeader(DataGridRowGroupHeader groupHeader)
		{
			groupHeader.IsRecycled = true;
			_recyclableGroupHeaders.Push(groupHeader);
		}

		internal void ClearElements(bool recycle)
		{
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0045: Expected O, but got Unknown
			ResetSlotIndexes();
			if (recycle)
			{
				foreach (Control scrollingElement in _scrollingElements)
				{
					if (scrollingElement is DataGridRow dataGridRow)
					{
						if (dataGridRow.IsRecyclable)
						{
							AddRecyclableRow(dataGridRow);
						}
						else
						{
							((Visual)dataGridRow).Clip = (Geometry)new RectangleGeometry();
						}
					}
					else if (scrollingElement is DataGridRowGroupHeader groupHeader)
					{
						AddRecylableRowGroupHeader(groupHeader);
					}
				}
			}
			else
			{
				_recyclableRows.Clear();
				_fullyRecycledRows.Clear();
				_recyclableGroupHeaders.Clear();
				_fullyRecycledGroupHeaders.Clear();
			}
			_scrollingElements.Clear();
		}

		internal void CorrectSlotsAfterDeletion(int slot, bool wasCollapsed)
		{
			if (wasCollapsed)
			{
				if (slot > FirstScrollingSlot)
				{
					LastScrollingSlot--;
				}
			}
			else if (_owner.IsSlotVisible(slot))
			{
				UnloadScrollingElement(slot, updateSlotInformation: true, wasDeleted: true);
			}
			if (slot < FirstScrollingSlot)
			{
				FirstScrollingSlot--;
				LastScrollingSlot--;
			}
		}

		internal void CorrectSlotsAfterInsertion(int slot, Control element, bool isCollapsed)
		{
			if (slot < FirstScrollingSlot)
			{
				FirstScrollingSlot++;
				LastScrollingSlot++;
			}
			else if (isCollapsed && slot <= LastScrollingSlot)
			{
				LastScrollingSlot++;
			}
			else if (_owner.GetPreviousVisibleSlot(slot) <= LastScrollingSlot || LastScrollingSlot == -1)
			{
				LoadScrollingSlot(slot, element, updateSlotInformation: true);
			}
		}

		private int GetCircularListIndex(int slot, bool wrap)
		{
			int num = slot - FirstScrollingSlot - _headScrollingElements - _owner.GetCollapsedSlotCount(FirstScrollingSlot, slot);
			if (!wrap)
			{
				return num;
			}
			return num % _scrollingElements.Count;
		}

		internal void FullyRecycleElements()
		{
			while (_recyclableRows.Count > 0)
			{
				DataGridRow dataGridRow = _recyclableRows.Pop();
				((AvaloniaObject)dataGridRow).SetCurrentValue<bool>(Visual.IsVisibleProperty, false);
				_fullyRecycledRows.Push(dataGridRow);
			}
			while (_recyclableGroupHeaders.Count > 0)
			{
				DataGridRowGroupHeader dataGridRowGroupHeader = _recyclableGroupHeaders.Pop();
				((AvaloniaObject)dataGridRowGroupHeader).SetCurrentValue<bool>(Visual.IsVisibleProperty, false);
				_fullyRecycledGroupHeaders.Push(dataGridRowGroupHeader);
			}
		}

		internal Control GetDisplayedElement(int slot)
		{
			return _scrollingElements[GetCircularListIndex(slot, wrap: true)];
		}

		internal DataGridRow? GetDisplayedRow(int rowIndex)
		{
			return GetDisplayedElement(_owner.SlotFromRowIndex(rowIndex)) as DataGridRow;
		}

		internal IEnumerable<Control> GetScrollingElements()
		{
			return GetScrollingElements(null);
		}

		internal IEnumerable<Control> GetScrollingElements(Predicate<object>? filter)
		{
			for (int i = 0; i < _scrollingElements.Count; i++)
			{
				Control val = _scrollingElements[(_headScrollingElements + i) % _scrollingElements.Count];
				if (filter == null || filter(val))
				{
					yield return val;
				}
			}
		}

		internal IEnumerable<Control> GetScrollingRows()
		{
			return GetScrollingElements((object element) => element is DataGridRow);
		}

		internal DataGridRow? GetUsedRow()
		{
			if (_recyclableRows.Count > 0)
			{
				return _recyclableRows.Pop();
			}
			if (_fullyRecycledRows.Count > 0)
			{
				DataGridRow dataGridRow = _fullyRecycledRows.Pop();
				((AvaloniaObject)dataGridRow).ClearValue<bool>(Visual.IsVisibleProperty);
				return dataGridRow;
			}
			return null;
		}

		internal void LoadScrollingSlot(int slot, Control element, bool updateSlotInformation)
		{
			if (_scrollingElements.Count == 0)
			{
				SetScrollingSlots(slot);
				_scrollingElements.Add(element);
				return;
			}
			if (updateSlotInformation)
			{
				if (slot < FirstScrollingSlot)
				{
					FirstScrollingSlot = slot;
				}
				else
				{
					LastScrollingSlot = _owner.GetNextVisibleSlot(LastScrollingSlot);
				}
			}
			int num = GetCircularListIndex(slot, wrap: false);
			if (num > _scrollingElements.Count)
			{
				num -= _scrollingElements.Count;
				_headScrollingElements++;
			}
			_scrollingElements.Insert(num, element);
		}

		private void ResetSlotIndexes()
		{
			SetScrollingSlots(-1);
			NumTotallyDisplayedScrollingElements = 0;
			_headScrollingElements = 0;
		}

		private void SetScrollingSlots(int newValue)
		{
			FirstScrollingSlot = newValue;
			LastScrollingSlot = newValue;
		}

		internal void UnloadScrollingElement(int slot, bool updateSlotInformation, bool wasDeleted)
		{
			int num = GetCircularListIndex(slot, wrap: false);
			if (num > _scrollingElements.Count)
			{
				num -= _scrollingElements.Count;
				_headScrollingElements--;
			}
			_scrollingElements.RemoveAt(num);
			if (updateSlotInformation)
			{
				if (slot == FirstScrollingSlot && !wasDeleted)
				{
					FirstScrollingSlot = _owner.GetNextVisibleSlot(FirstScrollingSlot);
				}
				else
				{
					LastScrollingSlot = _owner.GetPreviousVisibleSlot(LastScrollingSlot);
				}
				if (LastScrollingSlot < FirstScrollingSlot)
				{
					ResetSlotIndexes();
				}
			}
		}
	}
