			public static ArgumentOutOfRangeException ValueMustBeBetween(string paramName, string valueName, object lowValue, bool lowInclusive, object highValue, bool highInclusive)
			{
				string formatString = ((lowInclusive && highInclusive) ? "{0} must be greater than or equal to {1} and less than or equal to {2}." : ((lowInclusive && !highInclusive) ? "{0} must be greater than or equal to {1} and less than {2}." : ((!(!lowInclusive && highInclusive)) ? "{0} must be greater than {1} and less than {2}." : "{0} must be greater than {1} and less than or equal to {2}.")));
				return new ArgumentOutOfRangeException(paramName, Format(formatString, valueName, lowValue, highValue));
			}

