		public void RemoveIndexes(int startIndex, int count)
		{
			int num = FindRangeIndex(startIndex);
			if (num < 0)
			{
				num = 0;
			}
			for (int i = num; i < _list.Count; i++)
			{
				Range<T> range = _list[i];
				if (range.UpperBound < startIndex)
