				int num = 0;
				for (int i = 0; i < propertyPath.Length; i++)
				{
					if (flag)
					{
						if (propertyPath[i] == ')')
						{
							flag = false;
							num = i + 1;
						}
					}
					else if (propertyPath[i] == '(')
					{
						flag = true;
						if (num != i)
						{
							list.Add(propertyPath.Substring(num, i - num));
							num = i + 1;
						}
					}
					else if (propertyPath[i] == '.')
					{
						if (num != i)
						{
							list.Add(propertyPath.Substring(num, i - num));
